const crypto=require('node:crypto');const A=require('./accounts.cjs');const P=require('./question-plan.cjs');const S=require('./subjects.cjs');
async function start(plan,user,settings){const baseline=await A.progress(user.id,plan.subject||'termicas');await A.api('/rest/v1/maq_exam_sessions',{method:'POST',body:{id:plan.sessionId,user_id:user.id,subject:plan.subject||'termicas',topic:plan.unit,settings,baseline}});return baseline}
function attemptId(plan,userId){return crypto.createHash('sha256').update([userId,plan.sessionId,plan.cycle,plan.index].join(':')).digest('hex')}
async function cached(plan,userId){const rows=await A.api('/rest/v1/maq_attempts?id=eq.'+attemptId(plan,userId)+'&user_id=eq.'+userId+'&select=result');return rows?.[0]?.result}
async function record(plan,user,card,answer,settings){const row={id:attemptId(plan,user.id),user_id:user.id,session_id:plan.sessionId,subject:plan.subject||'termicas',question_id:card.id,topic:card.unit,score:answer.score,score_before_hint:answer.scoreBeforeHint??answer.score,correct:answer.score>=7,hint_used:plan.hintUsed===true,depth:settings.depth,scope:settings.scope,speed:settings.speed,response_text:answer.transcript.slice(0,6000),feedback:answer.feedback.slice(0,3000),omissions:answer.omissions,result:answer};const rows=await A.api('/rest/v1/maq_attempts?on_conflict=id',{method:'POST',body:row,headers:{Prefer:'resolution=ignore-duplicates,return=representation'}});if(!rows?.length)return await cached(plan,user.id)||answer;return answer}
async function revise(plan,user,previous,answer){const row={id:attemptId(plan,user.id),user_id:user.id,session_id:plan.sessionId,subject:plan.subject||'termicas',question_id:P.current(plan).id,topic:P.current(plan).unit,score:answer.score,score_before_hint:previous.scoreBeforeHint??previous.score,correct:answer.score>=7,hint_used:plan.hintUsed===true,depth:answer.depth||'normal',scope:plan.scope,speed:plan.speed,response_text:(previous.transcript+'\n[Ampliación del alumno] '+answer.transcript).slice(0,6000),feedback:answer.feedback.slice(0,3000),omissions:answer.omissions||[],result:answer};await A.api('/rest/v1/maq_attempts?on_conflict=id',{method:'POST',body:row,headers:{Prefer:'resolution=merge-duplicates,return=representation'}});return answer}
async function enrich(answer,plan,user){const progress=await A.progress(user.id,plan.subject||'termicas');const current=P.current(plan);return {...answer,learningProgress:progress,questionMeta:{id:current.id,topic:current.unit},questionStats:A.questionStats(progress,current.id)}}
async function comparison(plan,user,storedSession){const attempts=await A.sessionAttempts(plan.sessionId,user.id);const answered=attempts.filter(a=>a.result?.skipped!==true);const count=attempts.length,answeredCount=answered.length,penalty=attempts.reduce((sum,a)=>sum+(a.result?.skipped===true?Math.max(1,Number(a.result.skipPenalty)||1):0),0);const rawAverage=answeredCount?answered.reduce((s,a)=>s+Number(a.score),0)/answeredCount:0;const average=Math.max(0,rawAverage-penalty);const progress=await A.progress(user.id,plan.subject||'termicas');const baseline=storedSession?.baseline||{};return {attempts,progress,stats:{examAttempts:count,answeredCount,skippedCount:count-answeredCount,skipPenalty:penalty,examAverage:Math.round(average*100)/100,examAccuracy:answeredCount?Math.round(answered.filter(a=>a.correct).length/answeredCount*1000)/10:0,previousAttempts:baseline.attempts||0,previousAverage:Number(baseline.average||0),previousMastery:Number(baseline.mastery||0),currentMastery:Number(progress.mastery||0),averageDelta:baseline.attempts?Math.round((average-Number(baseline.average||0))*100)/100:null}}}
async function finish(answer,plan,user,storedSession){
 const c=await comparison(plan,user,storedSession),n=c.stats.answeredCount,skipped=c.stats.skippedCount;
 const topics=[...new Set(c.attempts.map(a=>a.topic))];const names=S.get(plan.subject||'termicas').topics;
 const gaps=new Map();for(const attempt of c.attempts)for(const gap of attempt.omissions||[])gaps.set(gap,(gaps.get(gap)||0)+1);
 const missing=[...gaps].sort((a,b)=>b[1]-a[1]).slice(0,5);const correct=c.attempts.filter(a=>a.correct).length;
 const scope=n===0?'No hay respuestas evaluables para valorar tus conocimientos.':n<3?'Es una muestra pequeña y parcial; no permite valorar tu preparación en toda la materia.':'Este resultado describe las preguntas trabajadas y no acredita el dominio de todo el programa.';
 const trend=!c.stats.previousAttempts?'No había intentos anteriores: este examen será tu primera referencia.':`Tu promedio anterior era ${c.stats.previousAverage.toFixed(2)}/10, sobre ${c.stats.previousAttempts} intentos. El promedio de esta práctica es ${c.stats.examAverage.toFixed(2)}/10. La comparación es orientativa porque los temas y la exigencia pueden variar.`;
 const overview=`Evaluamos ${n} respuesta${n===1?'':'s'}${skipped?` y omitiste ${skipped} pregunta${skipped===1?'':'s'}`:''} en ${topics.length} tema${topics.length===1?'':'s'}. ${scope} ${trend}`;
 const guidance=missing.length?'Para repasar: '+missing.slice(0,3).map(([gap,count])=>gap+(count>1?` (se repitió en ${count} respuestas)`:'')).join('; ')+'.':n?'No se registraron omisiones esenciales en estas respuestas; probá otras preguntas y mayor profundidad para ampliar la evidencia.':'';
 answer={...answer,score:c.stats.examAverage,comparison:c.stats,evaluated:n>0,finished:true,question:'',speech:overview+' '+guidance,feedbackSpeech:overview+' '+guidance,feedback:(topics.length?'Temas evaluados: '+topics.map(i=>names[i]).join(', ')+'. ':'')+`${correct} de ${n} respuestas alcanzaron 7/10 o más. ${skipped?`Penalización por omisiones: −${c.stats.skipPenalty} punto${c.stats.skipPenalty===1?'':'s'} según la importancia de cada pregunta. `:''}El avance global pasó de ${c.stats.previousMastery.toFixed(2)}% a ${c.stats.currentMastery.toFixed(2)}%. `+scope,strengths:correct?[`${correct} respuesta${correct===1?' alcanzó':'s alcanzaron'} el criterio de acierto (7/10 o más).`]:[],improvements:[...missing.map(([gap,count])=>gap+(count>1?` · Reiterado ${count} veces`:'')),...c.attempts.filter(a=>a.result?.skipped).map(a=>'Omitida: '+a.result.improvements?.[0]).filter(Boolean)],omissions:missing.map(([gap])=>gap),criteria:[],betterAnswer:'',hintPenalty:0};
 const summary={...answer};delete summary.learningProgress;delete summary.questionStats;
 await A.api('/rest/v1/maq_exam_sessions?id=eq.'+plan.sessionId+'&user_id=eq.'+user.id,{method:'PATCH',body:{status:'finished',finished_at:new Date().toISOString(),summary}});return {...answer,learningProgress:c.progress}
}
module.exports={start,attemptId,cached,record,revise,enrich,comparison,finish};
